namespace ghidra.trace.model.symbol;

using ghidra.util;

/**
 * A symbol view where names cannot be duplicated within the same parent namespace
 *
 * @param <T> the type of symbols in the view
 */
public interface TraceSymbolNoDuplicatesView<T> : TraceSymbolView<T> where T : TraceSymbol {

	/**
	 * Get the child of the given parent having the given name.
	 * 
	 * @param name the name of the symbol
	 * @param parent the parent namespace
	 * @return the symbol, or null
	 */
	T getChildNamed(string name, TraceNamespaceSymbol parent) {
		using (LockHold hold = getManager().getTrace().lockRead())
{
			foreach (T symbol in getChildrenNamed(name, parent)) {
				return symbol;
			}
			return null;
		}
	}

	/**
	 * A shorthand for {@link #getChildNamed(String, TraceNamespaceSymbol)} where parent is the
	 * global namespace.
	 * 
	 * @param name the name of the symbol
	 * @return the symbol, or null
	 */
	T getGlobalNamed(string name) {
		return getChildNamed(name, getManager().getGlobalNamespace());
	}
}
